:root {
  --bg: #0f1115;
  --panel: #1a1d24;
  --panel-2: #22262f;
  --border: #2e333d;
  --text: #e6e8ec;
  --muted: #9aa0aa;
  --accent: #4f8cff;
  --ok: #3ecf8e;
  --bad: #ff6b6b;
  --radius: 10px;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'PingFang SC', 'Microsoft YaHei', sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
}

.app { min-height: 100vh; display: flex; flex-direction: column; }

.topbar {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 12px 24px;
  background: var(--panel);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 10;
}
.brand { font-weight: 700; font-size: 18px; }
.tabs { display: flex; gap: 4px; }
.tab {
  background: transparent;
  border: none;
  color: var(--muted);
  padding: 8px 16px;
  border-radius: var(--radius);
  cursor: pointer;
  font-size: 15px;
}
.tab:hover { background: var(--panel-2); color: var(--text); }
.tab.active { background: var(--accent); color: #fff; }

.content { flex: 1; max-width: 900px; width: 100%; margin: 0 auto; padding: 24px; }

.card {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px;
  margin-bottom: 16px;
}

h1 { font-size: 22px; margin: 0 0 16px; }
h2 { font-size: 17px; margin: 0 0 12px; }

button.btn {
  background: var(--accent);
  color: #fff;
  border: none;
  padding: 9px 18px;
  border-radius: var(--radius);
  cursor: pointer;
  font-size: 15px;
}
button.btn:hover { filter: brightness(1.1); }
button.btn:disabled { opacity: 0.5; cursor: not-allowed; }
button.btn.ghost { background: var(--panel-2); color: var(--text); border: 1px solid var(--border); }
button.btn.danger { background: var(--bad); }

textarea, input, select {
  width: 100%;
  background: var(--panel-2);
  border: 1px solid var(--border);
  border-radius: 8px;
  color: var(--text);
  padding: 10px;
  font-size: 14px;
  font-family: inherit;
}
textarea { min-height: 160px; resize: vertical; }

label { display: block; margin: 10px 0 4px; color: var(--muted); font-size: 13px; }

.row { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; }
.spacer { flex: 1; }
.muted { color: var(--muted); }
.error { color: var(--bad); }
.ok { color: var(--ok); }

.option {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: 8px;
  margin-bottom: 8px;
  cursor: pointer;
}
.option:hover { background: var(--panel-2); }
.option.selected { border-color: var(--accent); background: rgba(79,140,255,0.1); }
.option.correct { border-color: var(--ok); background: rgba(62,207,142,0.12); }
.option.wrong { border-color: var(--bad); background: rgba(255,107,107,0.12); }

.tutor {
  background: var(--panel-2);
  border-radius: 8px;
  padding: 14px;
  margin-top: 12px;
}

.badge {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 6px;
  font-size: 12px;
  background: var(--panel-2);
  color: var(--muted);
}
.badge.ok { background: rgba(62,207,142,0.18); color: var(--ok); }
.badge.bad { background: rgba(255,107,107,0.18); color: var(--bad); }

.list-item {
  padding: 12px;
  border: 1px solid var(--border);
  border-radius: 8px;
  margin-bottom: 8px;
  cursor: pointer;
}
.list-item:hover { background: var(--panel-2); }

.field { margin-bottom: 6px; }

.dropzone {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 32px 20px;
  border: 2px dashed var(--border);
  border-radius: var(--radius);
  background: var(--panel-2);
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s;
}
.dropzone:hover { border-color: var(--accent); }
.dropzone.over {
  border-color: var(--accent);
  background: rgba(79,140,255,0.1);
}
.dropzone.disabled { cursor: default; opacity: 0.7; }

/* select/input 复用 input 基样式；.input 作为显式类名别名 */
.input {
  width: 100%;
  background: var(--panel-2);
  border: 1px solid var(--border);
  border-radius: 8px;
  color: var(--text);
  padding: 10px;
  font-size: 14px;
  font-family: inherit;
}

.report {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px;
  line-height: 1.7;
}

/* Markdown 渲染（讲解/答疑/学情报告）——暗色主题下的富文本排版 */
.md { line-height: 1.7; }
.md > *:first-child { margin-top: 0; }
.md > *:last-child { margin-bottom: 0; }
.md p { margin: 8px 0; }
.md ul, .md ol { margin: 8px 0; padding-left: 22px; }
.md li { margin: 4px 0; }
.md h1, .md h2, .md h3, .md h4 { margin: 14px 0 8px; line-height: 1.3; }
.md h1 { font-size: 20px; }
.md h2 { font-size: 18px; }
.md h3 { font-size: 16px; }
.md strong { color: var(--text); }
.md code {
  background: var(--panel-2);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 1px 5px;
  font-size: 13px;
}
.md pre {
  background: var(--panel-2);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 12px;
  overflow-x: auto;
}
.md pre code { background: none; border: none; padding: 0; }
.md blockquote {
  margin: 8px 0;
  padding-left: 12px;
  border-left: 3px solid var(--border);
  color: var(--muted);
}
.md table { border-collapse: collapse; margin: 8px 0; }
.md th, .md td { border: 1px solid var(--border); padding: 6px 10px; }
.md a { color: var(--accent); }

/* v2：练习/成绩单/学情可视化 —— 纯 CSS，不引图表库（DEC-26） */
.bar-fill.bad { background: var(--bad); }
.bar-row.clickable { cursor: pointer; border-radius: 6px; }
.bar-row.clickable:hover { background: var(--panel-2); }

/* v2：题号导航（QuestionNav） */
.qnav { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 12px; }
.qnav-cell {
  min-width: 34px;
  height: 34px;
  padding: 0 6px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--panel-2);
  color: var(--muted);
  cursor: pointer;
  font-size: 13px;
}
.qnav-cell:hover { border-color: var(--accent); color: var(--text); }
.qnav-cell.current { border-color: var(--accent); color: #fff; box-shadow: 0 0 0 1px var(--accent) inset; }
.qnav-cell.correct { background: rgba(62,207,142,0.18); color: var(--ok); border-color: var(--ok); }
.qnav-cell.wrong { background: rgba(255,107,107,0.18); color: var(--bad); border-color: var(--bad); }

/* v2：成绩单（Scorecard）+ 学情面板（InsightsPanel）共用条形 */
.score-big { text-align: center; padding: 8px 16px; }
.score-num { font-size: 40px; font-weight: 700; color: var(--accent); line-height: 1.1; }
.bar-row { display: flex; align-items: center; gap: 10px; margin-bottom: 6px; }
.bar-label { width: 120px; font-size: 13px; color: var(--muted); flex-shrink: 0; }
.bar-track { flex: 1; height: 14px; background: var(--panel-2); border-radius: 7px; overflow: hidden; border: 1px solid var(--border); }
.bar-fill { height: 100%; background: var(--accent); border-radius: 7px; transition: width 0.3s; }
.bar-val { width: 56px; text-align: right; font-size: 12px; flex-shrink: 0; }

/* v2：薄弱知识点条（错数占比，可点击下钻） */
.weak-row { display: flex; align-items: center; gap: 10px; margin-bottom: 6px; cursor: pointer; }
.weak-row:hover .weak-label { color: var(--accent); }
.weak-label { width: 120px; font-size: 13px; flex-shrink: 0; }
.weak-track { flex: 1; height: 14px; background: var(--panel-2); border-radius: 7px; overflow: hidden; border: 1px solid var(--border); }
.weak-fill { height: 100%; background: var(--bad); border-radius: 7px; }
.weak-val { width: 70px; text-align: right; font-size: 12px; flex-shrink: 0; }

